Printing


scanf.c

#include &lt;stdio.h&gt;

int main() {
    int a[1], b[1];
    scanf("%d,%d", a, b);
    printf("%d%d\n", a, b);
    return 0;
}


Can we print values back?

scanf.c: In function ‘main’:
scanf.c:6:14: warning: format ‘%d’ expects argument of type ‘int’, but argument 2 has type ‘int *’ [-Wformat=]
    6 |     printf("%d%d\n", a, b);
      |             ~^       ~
      |              |       |
      |              int     int *
      |             %ls
...

Printing


scanf.c

#include &lt;stdio.h&gt;

int main() {
    int a[1], b[1];
    scanf("%d,%d", a, b);
    printf("%d%d\n", a[0], b[0]);
    return 0;
}


Print needs values, not references.

$ gcc scanf.c && ./a.out
123,456
123456
$

Double it

Let’s say we want to double our input value.





scanf.c

#include &lt;stdio.h&gt;

int main() {
    int a[1], b[1];
    scanf("%d,%d", a, b);
    a[0] *= 2;
    b[0] *= 2;
    printf("%d%d\n", a[0], b[0]);
    return 0;
}


$ gcc scanf.c && ./a.out
123,456
246912
$ ./a.out
123,567
2461134
$

Uh oh.

Casts

That way is casts
In C, we prefix a value by a type (in parens) when assigning it to a variable.

1 is a value.
long is a type (usually the 64 bit type)
(long)1 is the value of 1 as a 64 bit type

long x = 0;
int y = 10;
x = (long)y;

Example



Create a variable x
It can refer to an int

x : list[int] # not x = [None]

Can’t use yet.

x[0] = 1 # this would error

#include &lt;stdio.h&gt;

int main() {
    int *x;
    char buf[4];
    buf[0] = 0xA;
    buf[1] = 0xB;
    buf[2] = 0xC;
    buf[3] = 0xD;
    x = (int *)buf;
    printf("%x\n", x[0]);
    return 0;
}

Example



Create variable buf
Array of 4 char.
Versus a char *:

The value buf holds some reference.

buf =  = [None] * 4


#include &lt;stdio.h&gt;

int main() {
    int *x;
    char buf[4];
    buf[0] = 0xA;
    buf[1] = 0xB;
    buf[2] = 0xC;
    buf[3] = 0xD;
    x = (int *)buf;
    printf("%x\n", x[0]);
    return 0;
}

Example



Easy-to-recognize values.

Can assign \(n\) at once but
But only for declares.
(The array could be the wrong size)



#include &lt;stdio.h&gt;

int main() {
    int *x;
    char buf[4];
    buf[0] = 0xA;
    buf[1] = 0xB;
    buf[2] = 0xC;
    buf[3] = 0xD;
    x = (int *)buf;
    printf("%x\n", x[0]);
    return 0;
}


char buf[4] = { 0xA, OxB, 0xC, 0xD }; /* okay */
/* say, char notbuf[2]; buf = notbuf; */
buf = {1,2,3,4}; /* banned - it isn't safe */

I lied



Tell gcc that no, really, buf is actually an array of integers.
It will believe you.
If you omit the cast, you will get a warning or error


#include &lt;stdio.h&gt;

int main() {
    int *x;
    char buf[4];
    buf[0] = 0xA;
    buf[1] = 0xB;
    buf[2] = 0xC;
    buf[3] = 0xD;
    x = (int *)buf;
    printf("%x\n", x[0]);
    return 0;
}

Ordering



Let’s see the output.
What order is that?

Same order within bytes

0x0 before 0xa

Reverse order within a number

0x0b before 0x0a




#include &lt;stdio.h&gt;

int main() {
    int *x;
    char buf[4];
    buf[0] = 0xA;
    buf[1] = 0xB;
    buf[2] = 0xC;
    buf[3] = 0xD;
    x = (int *)buf;
    printf("%x\n", x[0]);
    return 0;
}

I got no warnings/errors.

d0c0b0a

Script


tester.c

#include &lt;stdio.h&gt;

int main() {
        char x = 0;
        unsigned char y = 0;
        char buf[0x10];
        while (scanf("%s", buf)) {
                printf("%d, %u\n", x, y);
                x += 10;
                y += 10;
        }
        return 0;
}


Simply type any string then press ENTER.

More tests

Create somewhere to store an integer.
Scan input into said integer.
Cast integer to:

a (signed) char and print
an unsigned char and print.




tester.c

int main() {
        int x[0];
        while (scanf("%d", x)) {
                printf("%hhd, %u\n", (char)x[0], (unsigned char)x[0]);
        }
        return 0;
}

Look at ints


tester.c

#include &lt;stdio.h&gt;

int main() {
        int x[0];
        while (scanf("%d", x)) {
                printf("%d, %u, %032b\n", 
                *x, (unsigned)*x, x[0]);
        }
        return 0;
}

Stinger
#include &lt;stdio.h&gt;

int main() {
        int x[0], y[0];
        while (1) {
                scanf("%d %d", x, y);
                printf("%d, %u, %032b\n",
                                x[0]/y[0],
                                (unsigned)x[0]/y[0],
                                x[0]/y[0]);
        }
        return 0;
}

